"""Persistence of scenario results between scripts (pickle, regenerated by the scripts)."""

from __future__ import annotations

import logging
import pickle
from pathlib import Path
from typing import Any

from src.utils.config import PROJECT_ROOT

logger = logging.getLogger(__name__)

RAW_DIR = PROJECT_ROOT / "results" / "raw"


def save_result(result: Any, name: str, directory: Path = RAW_DIR) -> Path:
    """Pickle a scenario result to ``results/raw/<name>.pkl``."""
    directory.mkdir(parents=True, exist_ok=True)
    path = directory / f"{name}.pkl"
    with path.open("wb") as handle:
        pickle.dump(result, handle, protocol=pickle.HIGHEST_PROTOCOL)
    logger.info("Saved %s", path.relative_to(PROJECT_ROOT))
    return path


def load_result(name: str, directory: Path = RAW_DIR) -> Any:
    """Load a pickled scenario result; raises FileNotFoundError with a hint if missing."""
    path = directory / f"{name}.pkl"
    if not path.is_file():
        raise FileNotFoundError(f"{path} not found - run scripts/run_scenarios.py and "
                                "scripts/run_optimization.py first")
    with path.open("rb") as handle:
        return pickle.load(handle)
